// Ingest: turn one webhook payload (SARIF, ZAP JSON or lab JSON findings) into one item per finding.
// Payload contract (sent by CI / homelab runner):
// { source: { repo, ref, sha, runUrl, tool }, sarif?: <SARIF 2.1.0>, zap?: <ZAP traditional-json>, findings?: [<flat finding>] }
const out = [];
const sevFromScore = function (s) {
  const v = parseFloat(s);
  if (isNaN(v)) return null;
  if (v >= 9) return 'critical';
  if (v >= 7) return 'high';
  if (v >= 4) return 'medium';
  return 'low';
};
const sevFromLevel = { error: 'high', warning: 'medium', note: 'low', none: 'low' };
const zapRisk = { '3': 'high', '2': 'medium', '1': 'low', '0': 'info' };

for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const src = body.source || {};
  const base = { repo: src.repo || 'unknown', ref: src.ref || '', sha: src.sha || '', runUrl: src.runUrl || '', receivedAt: new Date().toISOString() };

  if (body.sarif && Array.isArray(body.sarif.runs)) {
    for (const run of body.sarif.runs) {
      const tool = ((run.tool || {}).driver || {}).name || src.tool || 'sarif';
      const rules = {};
      for (const r of (((run.tool || {}).driver || {}).rules || [])) rules[r.id] = r;
      for (const res of (run.results || [])) {
        const rule = rules[res.ruleId] || {};
        const props = rule.properties || {};
        const loc = (((res.locations || [])[0] || {}).physicalLocation) || {};
        const tags = (props.tags || []).join(' ').toLowerCase();
        const isSecret = /gitleaks|trufflehog|secret/i.test(tool) || tags.indexOf('secret') >= 0;
        let severity = sevFromScore(props['security-severity']) || sevFromLevel[res.level || 'warning'] || 'medium';
        if (isSecret) severity = 'critical';
        out.push({ json: Object.assign({}, base, {
          kind: isSecret ? 'secret' : 'sast',
          tool: tool,
          rule: res.ruleId || 'unknown',
          title: (rule.shortDescription && rule.shortDescription.text) || res.ruleId,
          message: ((res.message || {}).text || '').slice(0, 1500),
          severity: severity,
          confidence: String(props.confidence || props.precision || 'unknown').toLowerCase(),
          file: ((loc.artifactLocation || {}).uri) || '',
          line: ((loc.region || {}).startLine) || 0,
          url: '', param: ''
        }) });
      }
    }
  }

  if (body.zap && Array.isArray(body.zap.site)) {
    for (const site of body.zap.site) {
      for (const alert of (site.alerts || [])) {
        const sev = zapRisk[String(alert.riskcode)] || 'low';
        if (sev === 'info') continue;
        for (const inst of (alert.instances || [{}])) {
          out.push({ json: Object.assign({}, base, {
            kind: 'dast', tool: 'zap', rule: 'zap-' + alert.pluginid,
            title: alert.name || alert.alert,
            message: String(alert.desc || '').replace(/<[^>]+>/g, '').slice(0, 1500),
            severity: sev,
            confidence: ({ '3': 'high', '2': 'medium', '1': 'low' })[String(alert.confidence)] || 'unknown',
            file: '', line: 0,
            url: inst.uri || site['@name'] || '', param: inst.param || '', method: inst.method || ''
          }) });
        }
      }
    }
  }

  for (const f of (body.findings || [])) {
    out.push({ json: Object.assign({}, base, {
      kind: f.kind || (f.url ? 'dast' : 'sast'), tool: f.tool || src.tool || 'custom',
      rule: f.rule || 'unknown', title: f.title || f.rule, message: f.message || '',
      severity: String(f.severity || 'medium').toLowerCase(), confidence: f.confidence || 'high',
      file: f.file || '', line: f.line || 0, url: f.url || '', param: f.param || '', method: f.method || ''
    }) });
  }
}
return out;

// Enrich: owner (mock CODEOWNERS), app tier, exposure, SLA due date, dedupe key.
// CODEOWNERS is mirrored here as a mock; last matching pattern wins, same as GitHub.
const codeowners = {
  'dankmessiah/appsec-rpg': [
    { pattern: '', owner: '@dankmessiah' },
    { pattern: 'server/', owner: '@game-backend' },
    { pattern: 'shared/', owner: '@game-backend' },
    { pattern: 'db/', owner: '@game-backend' },
    { pattern: 'public/', owner: '@game-frontend' },
    { pattern: '.github/', owner: '@platform' },
    { pattern: 'Dockerfile', owner: '@platform' },
    { pattern: 'docker-compose.yml', owner: '@platform' }
  ],
  'dankmessiah/juice-shop': [
    { pattern: '', owner: '@juice-maintainers' },
    { pattern: 'routes/', owner: '@juice-backend' },
    { pattern: 'lib/', owner: '@juice-backend' },
    { pattern: 'frontend/', owner: '@juice-frontend' }
  ]
};
const apps = {
  'dankmessiah/appsec-rpg': { tier: 1, exposure: 'lan-staging', dataClass: 'user-accounts' },
  'dankmessiah/juice-shop': { tier: 3, exposure: 'ci-only', dataClass: 'none (calibration)' }
};
const slaDays = { critical: 7, high: 30, medium: 90, low: 180 };
const jiraPriority = { critical: 'Highest', high: 'High', medium: 'Medium', low: 'Low' };

return $input.all().map(function (item) {
  const f = item.json;
  const rules = codeowners[f.repo] || [{ pattern: '', owner: '@appsec-triage' }];
  let owner = rules[0].owner;
  for (const rule of rules) {
    if (rule.pattern === '' || (f.file || '').replace(/^\.?\//, '').indexOf(rule.pattern) === 0) owner = rule.owner;
  }
  if (f.kind === 'dast') owner = f.repo === 'dankmessiah/appsec-rpg' ? '@game-backend' : owner;
  const app = apps[f.repo] || { tier: 3, exposure: 'unknown', dataClass: 'unknown' };
  let severity = f.severity;
  // Exposure bump: Tier 1 + reachable + high-confidence High becomes Critical for routing.
  if (app.tier === 1 && severity === 'high' && f.confidence === 'high' && f.kind !== 'sast') severity = 'critical';
  const due = new Date(Date.now() + (slaDays[severity] || 180) * 86400000).toISOString().slice(0, 10);
  const dedupeKey = (f.kind === 'dast')
    ? [f.repo, f.rule, (f.url || '').split('?')[0], f.param || ''].join('|')
    : [f.repo, f.rule, f.file, f.line].join('|');
  return { json: Object.assign({}, f, {
    severity: severity, owner: owner, tier: app.tier, exposure: app.exposure, dataClass: app.dataClass,
    slaDays: slaDays[severity] || 180, dueDate: due, jiraPriority: jiraPriority[severity] || 'Low',
    dedupeKey: dedupeKey,
    runbook: f.kind === 'secret' ? 'https://github.com/dankmessiah/appsec-rpg/blob/main/docs/lab/runbook-exposed-secret.md' : ''
  }) };
});

